def is_blank(v):
    return v is None or (isinstance(v, str) and v.strip() == "")

def norm(v):
    """Normalize values so numeric strings like '101' match numeric cells like 101 or 101.0."""
    if is_blank(v):
        return None
    if isinstance(v, bool):
        return str(v).strip().lower()
    if isinstance(v, (datetime, date, time)):
        return v
    if isinstance(v, (int, float, Decimal)):
        try:
            d = Decimal(str(v))
            if d == d.to_integral_value():
                return str(int(d))
            return format(d.normalize(), "f")
        except (InvalidOperation, ValueError):
            return str(v).strip()
    s = str(v).strip()
    try:
        d = Decimal(s)
        if d == d.to_integral_value():
            return str(int(d))
        return format(d.normalize(), "f")
    except (InvalidOperation, ValueError):
        return s

# Source table is in A:C, with headers in row 1.
headers = [ws.cell(row=1, column=c).value for c in range(1, 4)]

# Criteria arrays are listed in G:I, one array per column, starting below their headers.
criteria_cols = [7, 8, 9]  # G, H, I
criteria_sets = []
for crit_col in criteria_cols:
    values = set()
    for r in range(2, ws.max_row + 1):
        v = ws.cell(row=r, column=crit_col).value
        nv = norm(v)
        if nv is not None:
            values.add(nv)
    criteria_sets.append(values)

# Find actual extent of source data in A:C.
last_source_row = 1
for r in range(2, ws.max_row + 1):
    if any(not is_blank(ws.cell(row=r, column=c).value) for c in range(1, 4)):
        last_source_row = r

# Filter rows: intersection of the three column-specific criteria arrays.
filtered_rows = []
for r in range(2, last_source_row + 1):
    row_vals = [ws.cell(row=r, column=c).value for c in range(1, 4)]
    keep = True
    for i, val in enumerate(row_vals):
        if criteria_sets[i] and norm(val) not in criteria_sets[i]:
            keep = False
            break
    if keep:
        filtered_rows.append(row_vals)

# Clear only the permitted output range A1:C13.
for r in range(out_min_row, out_max_row + 1):
    for c in range(out_min_col, out_max_col + 1):
        ws.cell(row=r, column=c).value = None

# Write headers and as many filtered rows as fit in A1:C13.
for c, v in enumerate(headers, start=1):
    ws.cell(row=1, column=c).value = v

for idx, row_vals in enumerate(filtered_rows, start=2):
    if idx > out_max_row:
        break
    for c, v in enumerate(row_vals, start=1):
        ws.cell(row=idx, column=c).value = v

os.makedirs(os.path.dirname(output_path), exist_ok=True)
wb.save(output_path)
